(5493316, 792108, 63812, '<td valign="top">excellent image 9</td>', 'excellent image 9', '2009-05-20 02:14:56.000000', NULL, 1),
(5493319, 792363, 60173, '<td valign="top">From the thumbnail I didn''t expect to like this, but I''m pleasantly surprised. It''s a great abstract-like photo with great colors. I''m probably looking too hard, but it almost looks like bug ships flying through space.</td>', 'From the thumbnail I didn''t expect to like this, but I''m pleasantly surprised. It''s a great abstract-like photo with great colors. I''m probably looking too hard, but it almost looks like bug ships flying through space.', '2009-05-20 02:15:54.000000', NULL, 1),
(5493334, 791146, 54645, '<td valign="top">I really like the gloominess of the image. Empty. Lonely.</td>', 'I really like the gloominess of the image. Empty. Lonely.', '2009-05-20 02:26:14.000000', NULL, 1),
(5493336, 792129, 6804, '<td valign="top">This is a really great composition!  Its seedy and run-down which make for an awesome grunge appeal.<br/>I like the colors and the more-natural, less-processed appearance of the shot.  I would, however, like to see a little more detail in the shadows of the hot and cold taps.  <br/>There are quite a handful of diagonal lines in this image.  It is difficult to keep diagonal lines free from degradation.  Some are showing a little more bitmap in areas. (Not horrible, but noticeable).  Sometimes the diagonal lines can be improved in the way you apply the sharpen tools with the resize.   It helps a great deal to avoid over-cropping the image as well.</td>', 'This is a really great composition!  Its seedy and run-down which make for an awesome grunge appeal.I like the colors and the more-natural, less-processed appearance of the shot.  I would, however, like to see a little more detail in the shadows of the hot and cold taps.  There are quite a handful of diagonal lines in this image.  It is difficult to keep diagonal lines free from degradation.  Some are showing a little more bitmap in areas. (Not horrible, but noticeable).  Sometimes the diagonal lines can be improved in the way you apply the sharpen tools with the resize.   It helps a great deal to avoid over-cropping the image as well.', '2009-05-20 02:26:35.000000', NULL, 1),
(5493352, 792158, 6804, '<td valign="top">Very cool shot!</td>', 'Very cool shot!', '2009-05-20 02:42:14.000000', NULL, 1),
